actions.command:
bash -lc "
DOCKERFILE=\"$TARGET_DIR/Dockerfile\";
if [ -f \"$DOCKERFILE\" ]; then
  sed -i '/^RUN pip install -r docker-requirements.txt/a RUN apt-get update && apt-get install -y patch' \"$DOCKERFILE\";
  echo 'Patched Dockerfile';
fi;
SCRIPT=\$(find \"$TARGET_DIR\" -type f -name 'run_test_entrypoint.sh' | head -n 1);
if [ -n \"\$SCRIPT\" ]; then
  awk '/patch/ && !found {print \"if ! command -v patch >/dev/null 2>&1; then echo \\\"Error: '\\''patch'\\'' utility not found. Install it in the Docker image.\\\" >&2; exit 127; fi\"; found=1} {print}' \"\$SCRIPT\" > \"\$SCRIPT.tmp\" && mv \"\$SCRIPT.tmp\" \"\$SCRIPT\";
  echo 'Patched script';
fi
"

